70: /* Long enough for the slowest shape to finish leaving. */
71: const LEAVE_MS = 950;
72: 
73: type LayerProps = {
74:   shapes: Shape[];
75:   leaving?: boolean;
76: };
77: 
78: function ShapeLayer({ shapes, leaving = false }: LayerProps) {
79:   return (
80:     <div className={`backdrop__layer ${leaving ? 'is-leaving' : 'is-entering'}`}>
81:       {shapes.map((shape, index) => (
82:         <span
83:           key={index}
84:           className="backdrop__flight"
85:           style={
86:             {
87:               '--t': shape.top,
88:               '--l': shape.left,
89:               '--stagger': `${index * 70}ms`,
90:             } as CSSProperties
91:           }
92:         >
93:           <span
94:             className="backdrop__shape"
95:             style={
96:               {
97:                 '--c': shape.color,
98:                 '--w': `${shape.width}px`,
99:                 '--h': `${shape.height}px`,
100:                 '--r': shape.radius,
101:                 '--mix': `${shape.mix}%`,
102:                 '--delay': shape.delay,
103:                 '--dur': shape.duration,
104:               } as CSSProperties
105:             }
106:           />
107:         </span>
108:       ))}
109:     </div>
110:   );
111: }
112: 
113: export function Backdrop() {
114:   const [current, setCurrent] = useState(0);
115:   const [previous, setPrevious] = useState<number | null>(null);
116:   const currentRef = useRef(0);
117:   const reducedRef = useRef(false);
118: 
119:   useEffect(() => {
120:     const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
121:     reducedRef.current = motion.matches;
122: 
123:     const onMotion = (event: MediaQueryListEvent) => {
124:       reducedRef.current = event.matches;
125:     };
126: 
127:     let frame = 0;
128:     const measure = () => {
129:       frame = 0;
130:       /* the scene switches once a section crosses the upper third of the screen */
131:       const line = window.innerHeight * 0.42;
132:       let next = 0;
133:       sceneIds.forEach((id, index) => {
134:         const node = document.getElementById(id);
135:         if (node && node.getBoundingClientRect().top <= line) next = index;
136:       });
137:       if (next === currentRef.current) return;
138:       if (!reducedRef.current) setPrevious(currentRef.current);
139:       currentRef.current = next;
140:       setCurrent(next);
141:     };
142: 
143:     const onScroll = () => {
144:       if (frame) return;
145:       frame = requestAnimationFrame(measure);
146:     };
147: 
148:     measure();
149:     window.addEventListener('scroll', onScroll, { passive: true });
150:     window.addEventListener('resize', onScroll);
151:     return () => {
152:       cancelAnimationFrame(frame);
153:       window.removeEventListener('scroll', onScroll);
154:       window.removeEventListener('resize', onScroll);
155:       motion.removeEventListener('change', onMotion);
156:     };
157:   }, []);
158: 
159:   useEffect(() => {
160:     if (previous === null) return;
161:     const timer = window.setTimeout(() => setPrevious(null), LEAVE_MS);
162:     return () => window.clearTimeout(timer);
163:   }, [previous]);
164: 
165:   return (
166:     <div className="backdrop" aria-hidden="true">
167:       {previous !== null && previous !== current ? (
168:         <ShapeLayer key={`out-${previous}`} shapes={scenes[previous]} leaving />
169:       ) : null}
170:       <ShapeLayer key={current} shapes={scenes[current]} />
171:     </div>
172:   );
173: }

