3: /**
4:  * A small accent dot that trails the mouse with easing.
5:  * It is decorative: the native cursor stays, and the dot never blocks clicks.
6:  */
7: export function CursorDot() {
8:   const ref = useRef<HTMLDivElement>(null);
9: 
10:   useEffect(() => {
11:     const el = ref.current;
12:     if (!el) return;
13: 
14:     const coarse = window.matchMedia('(pointer: coarse)');
15:     const still = window.matchMedia('(prefers-reduced-motion: reduce)');
16:     if (coarse.matches || still.matches) return;
17: 
18:     let targetX = window.innerWidth / 2;
19:     let targetY = window.innerHeight / 2;
20:     let x = targetX;
21:     let y = targetY;
22:     let frame = 0;
23:     let visible = false;
24: 
25:     const show = () => {
26:       if (visible) return;
27:       visible = true;
28:       x = targetX;
29:       y = targetY;
30:       el.classList.add('is-visible');
31:     };
32: 
33:     const hide = () => {
34:       visible = false;
35:       el.classList.remove('is-visible', 'is-active');
36:     };
37: 
38:     const move = (event: PointerEvent) => {
39:       if (event.pointerType !== 'mouse') return;
40:       targetX = event.clientX;
41:       targetY = event.clientY;
42:       show();
43: 
44:       const interactive = (event.target as Element | null)?.closest(
45:         'a, button, [role="button"], input, select, textarea, label, summary',
46:       );
47:       el.classList.toggle('is-active', Boolean(interactive));
48:     };
49: 
50:     const tick = () => {
51:       x += (targetX - x) * 0.16;
52:       y += (targetY - y) * 0.16;
53:       el.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0)`;
54:       frame = requestAnimationFrame(tick);
55:     };
56: 
57:     window.addEventListener('pointermove', move, { passive: true });
58:     document.addEventListener('pointerleave', hide);
59:     window.addEventListener('blur', hide);
60:     frame = requestAnimationFrame(tick);
61: 
62:     return () => {
63:       cancelAnimationFrame(frame);
64:       window.removeEventListener('pointermove', move);
65:       document.removeEventListener('pointerleave', hide);
66:       window.removeEventListener('blur', hide);
67:     };
68:   }, []);
69: 
70:   return <div ref={ref} className="cursor-dot" aria-hidden="true" />;
71: }

