```tsx
import { useEffect } from 'react';

export function ClickRipple() {
  useEffect(() => {
    const still = window.matchMedia('(prefers-reduced-motion: reduce)');
    const coarse = window.matchMedia('(pointer: coarse)'); // maybe allow touch? ripple on touch is native-like; but avoid fighting scroll. Only mouse.
    if (still.matches || coarse.matches) return;

    let host: HTMLDivElement | null = null;
    const onDown = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse' || event.button !== 0) return;
      ...
      const span = document.createElement('span');
      span.className = 'click-ripple';
      span.style.left = `${event.clientX}px`;
      span.style.top = `${event.clientY}px`;
      document.body.appendChild(span);
      span.addEventListener('animationend', () => span.remove(), { once: true });
      // fallback timeout?
    };
    window.addEventListener('pointerdown', onDown, { passive: true });
    return ...
  }, []);
  return null;
}
```

No need host; append to body. But React strict mode may mount twice in dev; cleanup removes listener. Fine. Use CSS:

```css
